 async function exportFile(format:'pdf'|'svg'|'json'|'zip'|'png'){if(!doc||busyRef.current)return;if(format==='json'){downloadBlob(new Blob([JSON.stringify(doc)],{type:'application/json'}),fileName(doc.title)+'.fivegen.json');say('Editable design downloaded. Includes your current unsaved changes.');return;}busyRef.current=true;setBusy('export');setError('');try{await onSave();onBusyChange?.(true);const query=new URLSearchParams({format:format==='png'?'svg':format,...(page&&(format==='png'||format==='svg')?{pageId:page.id}:{})}),response=await fetch(`/api/builder/${encodeURIComponent(productId)}/design/export?${query}`,{cache:'no-store'});if(!response.ok){let message='This design could not be exported.';try{message=((await response.json()) as {error?:string}).error||message;}catch{}throw new Error(message);}const blob=await response.blob();if(format==='png'&&page){const url=URL.createObjectURL(blob);try{const image=new Image();image.src=url;await image.decode();const scale=Math.min(2,Math.sqrt(24000000/(page.width*page.height))),canvas=window.document.createElement('canvas');canvas.width=Math.round(page.width*scale);canvas.height=Math.round(page.height*scale);const context=canvas.getContext('2d');if(!context)throw new Error('PNG export is unavailable in this browser. Download SVG or PDF instead.');context.drawImage(image,0,0,canvas.width,canvas.height);const png=await new Promise<Blob>((resolve,reject)=>canvas.toBlob(value=>value?resolve(value):reject(new Error('PNG could not be prepared.')),'image/png'));downloadBlob(png,fileName(doc.title)+'-'+fileName(page.name)+'.png');}finally{URL.revokeObjectURL(url);}}else downloadBlob(blob,fileName(doc.title)+(format==='svg'&&page?'-'+fileName(page.name):'')+'.'+format);say(format==='pdf'?'PDF downloaded. Print at actual size; review your printer’s margins.':'Design downloaded.');}catch(reason){setError(errorText(reason));}finally{busyRef.current=false;setBusy('');onBusyChange?.(false);}}
 async function uploadImage(file:File){
  if(!doc||!page||busyRef.current)return;
  if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>8000000){setError('Choose a PNG, JPEG or WebP image smaller than 8 MB.');return;}
  if(page.elements.length>=120||designImageIds(doc).length>=20){setError('This page or design has reached its layer or image limit. Remove a layer before adding another image.');return;}
  busyRef.current=true;setBusy('upload');setError('');onBusyChange?.(true);
  try{
   const bitmap=await createImageBitmap(file),width=bitmap.width,height=bitmap.height;bitmap.close();
   const response=await fetch(`/api/products/${encodeURIComponent(productId)}/uploads?name=${encodeURIComponent(file.name)}`,{method:'POST',headers:{'Content-Type':file.type,'X-File-Size':String(file.size)},body:file});
   const data=await response.json() as {upload?:{id:string;status:string};error?:string};
   if(!response.ok||!data.upload?.id||data.upload.status!=='completed')throw new Error(data.error||'The image could not be verified.');
   addImageLayer(data.upload.id,width,height,page.id);
  }catch(reason){setError(errorText(reason));}finally{busyRef.current=false;setBusy('');onBusyChange?.(false);}
 }
 async function importDesign(file:File){try{if(file.size>240000)throw new Error('Choose a FiveGen design JSON file up to 240 KB.');const value=designDocumentSchema.parse(JSON.parse(await file.text()));const next={...value,pages:value.pages.map(page=>({...page,id:crypto.randomUUID(),elements:page.elements.map(element=>({...element,id:crypto.randomUUID()}))}))};const referenced=designImageIds(next);if(referenced.length){const response=await fetch(`/api/products/${encodeURIComponent(productId)}/uploads`,{cache:'no-store'}),data=await response.json() as {uploads?:{id:string;status:string;mime:string;purpose:string}[];error?:string};if(!response.ok)throw new Error(data.error||'Could not verify the images in this file.');const knownImages=new Set((data.uploads||[]).filter(item=>item.status==='completed'&&item.purpose==='product'&&['image/png','image/jpeg','image/webp'].includes(item.mime)).map(item=>item.id));if(referenced.some(id=>!knownImages.has(id)))throw new Error('This file uses images from another product or unavailable originals. Upload those images here and add them as new layers; vector-only designs import directly.');}if(doc&&doc.pages.some(page=>page.elements.length))setTemplate(next);else applyDocument(next);}catch(reason){setError(errorText(reason));}}
 const toolbarDisabled=Boolean(busy),selectedLocked=items.length>0&&items.every(value=>value.locked);
