  <header className="ds-heading"><div><span className="ds-eyebrow"><Palette size={14}/>DESIGN STUDIO</span><h2>{doc?'Make it yours.':'What would you like to design?'}</h2><p>{doc?'Edit every layer. Create something worth keeping.':'Invitations, colouring books, printables and graphics. Start with a template or your own idea.'}</p></div><div className="ds-heading-actions">{doc&&<button type="button" className="ds-secondary" aria-pressed={focusMode} onClick={()=>setFocusMode(value=>!value)}>{focusMode?<Minimize2 size={15}/>:<Maximize2 size={15}/>} {focusMode?'Back to product':'Focus editor'}</button>}<button className="ds-secondary" type="button" onClick={()=>importInput.current?.click()} disabled={toolbarDisabled}><Upload size={15}/>Open design</button>{doc&&<><button className="ds-secondary" type="button" onClick={()=>void save()} disabled={toolbarDisabled}><Save size={15}/>{busy==='save'?'Saving…':'Save design'}</button><DropdownMenu><DropdownMenuTrigger asChild><button className="ds-primary" type="button" disabled={toolbarDisabled}><Download size={16}/>{busy==='export'?'Preparing…':'Download'}<ChevronDown size={14}/></button></DropdownMenuTrigger><DropdownMenuContent align="end"><DropdownMenuItem onSelect={()=>void exportFile('pdf')}>PDF · all pages</DropdownMenuItem><DropdownMenuItem onSelect={()=>void exportFile('png')}>PNG · current page</DropdownMenuItem><DropdownMenuItem onSelect={()=>void exportFile('svg')}>SVG · current page</DropdownMenuItem><DropdownMenuItem onSelect={()=>void exportFile('json')}>Editable FiveGen file</DropdownMenuItem><DropdownMenuItem onSelect={()=>void exportFile('zip')}>ZIP · complete design</DropdownMenuItem></DropdownMenuContent></DropdownMenu></>}</div></header>
